from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")
old = """中間イベント以降は、前進を続けるごとに最終イベントが出現する確率が上昇する。\n  5枚目以降は d66 の出目を確認し、該当した場合は通常のマップタイルではなく最終イベントが出現する。\n\n最終イベントの出現条件は以下の通りである。\n\n- 5枚目……通常どおり（最終イベントは出現しない）\n- 6枚目……出目が 11～16 なら最終イベントが出現\n- 7枚目……出目が 11～26 なら最終イベントが出現\n- 8枚目……出目が 11～36 なら最終イベントが出現\n- 9枚目……出目が 11～46 なら最終イベントが出現\n- 10枚目……出目が 11～56 なら最終イベントが出現\n- 11枚目……必ず最終イベントが出現\n\nプレイヤーは、次の手順を繰り返して作戦を進める。\n\n1. 次の区域へ進出する\n2. 必要に応じて最終イベント出現判定を行う\n3. d66 をロールする\n4. 該当するマップイベントを解決する\n"""
new = """中間イベント以降は、前進を続けるごとに最終イベントが出現する確率が上昇する。\n  5枚目以降（11枚目を除く）は d66 をロールし、「次のd66」に対する修正・固定・振り直し等がある場合はすべて適用して結果を確定する。その確定後の d66 結果が下記条件に該当した場合、通常のマップタイルは処理せず最終イベントが出現する。\n\n最終イベントの出現条件は以下の通りである。\n\n- 5枚目……通常どおり（最終イベントは出現しない）\n- 6枚目……確定後の出目が 11～16 なら最終イベントが出現\n- 7枚目……確定後の出目が 11～26 なら最終イベントが出現\n- 8枚目……確定後の出目が 11～36 なら最終イベントが出現\n- 9枚目……確定後の出目が 11～46 なら最終イベントが出現\n- 10枚目……確定後の出目が 11～56 なら最終イベントが出現\n- 11枚目……d66を振らず、必ず最終イベントが出現\n\nプレイヤーは、次の手順を繰り返して作戦を進める。\n\n1. 次の区域へ進出する。\n2. 11枚目なら d66 を振らず、そのまま最終イベントへ進む。\n3. 11枚目以外では d66 をロールする。\n4. 「次のd66」に対する修正・固定・振り直し等があれば適用し、d66 の最終結果を確定する。\n5. 6～10枚目では、確定後の d66 結果がその枚数の最終イベント出現条件に該当するか判定する。該当した場合は通常マップイベントを処理せず最終イベントへ進む。\n6. 最終イベントが出現しなかった場合は、確定後の d66 結果に対応する通常のマップイベントを解決する。\n"""
if s.count(old) != 1:
    raise SystemExit(f"final-event order marker count must be 1, got {s.count(old)}")
scenario.write_text(s.replace(old, new, 1), encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 30. Black Sun 最終イベント判定とd66補正の処理順 — 採用済み"
section = """

## 30. Black Sun 最終イベント判定とd66補正の処理順 — 採用済み

ユーザー承認により、一本道モードの最終イベント出現判定は、d66をロールした後に「次のd66」に対する修正・固定・振り直し等を適用し、その確定後の結果を使って行う。

- 5枚目は確定後のd66で通常マップを処理し、最終イベントは出現しない。
- 6～10枚目は、まずd66をロールし、適用可能な「次のd66」効果をすべて処理して最終結果を確定する。
- その確定後のd66結果が各枚数の出現範囲に入っていれば、通常マップイベントを処理せず最終イベントへ進む。
- 出現範囲外なら、確定後のd66結果に対応する通常マップイベントを処理する。
- 11枚目はd66を振らず、必ず最終イベントへ進む。
- 出目12、16、45等の「次のd66」に影響する効果は、この最終イベント判定より前に適用する。

これにより、一本道モード本文中の処理順の矛盾を解消し、d66操作効果が通常マップだけでなく最終イベント到達タイミングにも影響する。
"""
if heading not in a:
    audit.write_text(a.rstrip() + section + "\n", encoding="utf-8")
